// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListAiProviders The Learner's saved AI Providers
	// (GET /ai-providers)
	ListAiProviders(w http.ResponseWriter, r *http.Request)
	// CreateAiProvider Save a new AI Provider
	// (POST /ai-providers)
	CreateAiProvider(w http.ResponseWriter, r *http.Request)
	// DeleteAiProvider Remove an AI Provider
	// (DELETE /ai-providers/{id})
	DeleteAiProvider(w http.ResponseWriter, r *http.Request, id ProviderId)
	// GetAiProvider One AI Provider
	// (GET /ai-providers/{id})
	GetAiProvider(w http.ResponseWriter, r *http.Request, id ProviderId)
	// UpdateAiProvider Change an AI Provider
	// (PATCH /ai-providers/{id})
	UpdateAiProvider(w http.ResponseWriter, r *http.Request, id ProviderId)
	// TestAiProvider Check that the provider answers a tiny chat request
	// (POST /ai-providers/{id}/test)
	TestAiProvider(w http.ResponseWriter, r *http.Request, id ProviderId)
	// ListAiTasks Which AI Provider each task uses
	// (GET /ai-tasks)
	ListAiTasks(w http.ResponseWriter, r *http.Request)
	// ClearAiTask Leave a task without an AI Provider
	// (DELETE /ai-tasks/{task})
	ClearAiTask(w http.ResponseWriter, r *http.Request, task AiTask)
	// SetAiTask Choose the AI Provider for a task
	// (PUT /ai-tasks/{task})
	SetAiTask(w http.ResponseWriter, r *http.Request, task AiTask)
	// Login Exchange a username and password for a session token
	// (POST /auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Logout Invalidate the current session token
	// (POST /auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// GetFocusSet The rotating Focus Set of low-Mastery Known Items
	// (GET /focus-set)
	GetFocusSet(w http.ResponseWriter, r *http.Request)
	// ListGrammarPoints Grammar points in catalogue order (level N5→N1, then catalogue number)
	// (GET /grammar/points)
	ListGrammarPoints(w http.ResponseWriter, r *http.Request, params ListGrammarPointsParams)
	// GetGrammarPoint Read a grammar point, generating missing content on first read
	// (GET /grammar/points/{id})
	GetGrammarPoint(w http.ResponseWriter, r *http.Request, id GrammarPointId)
	// UpdateGrammarPoint Edit the explanation of a grammar point
	// (PATCH /grammar/points/{id})
	UpdateGrammarPoint(w http.ResponseWriter, r *http.Request, id GrammarPointId)
	// GenerateGrammarExamples Generate example sentences, validating each against JMdict before storing it
	// (POST /grammar/points/{id}/examples)
	GenerateGrammarExamples(w http.ResponseWriter, r *http.Request, id GrammarPointId)
	// RegenerateGrammarExplanation Regenerate the explanation, replacing any existing one
	// (POST /grammar/points/{id}/explanation/regenerate)
	RegenerateGrammarExplanation(w http.ResponseWriter, r *http.Request, id GrammarPointId)
	// ListGrammarReviewItems MaruMori grammar the Learner knows that the Catalogue Matching could not resolve cleanly
	// (GET /grammar/review)
	ListGrammarReviewItems(w http.ResponseWriter, r *http.Request, params ListGrammarReviewItemsParams)
	// GetHealth Liveness and database connectivity check
	// (GET /health)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// GetMaruMoriStatus Whether MaruMori is connected, and what the last Sync found
	// (GET /marumori)
	GetMaruMoriStatus(w http.ResponseWriter, r *http.Request)
	// DeleteMaruMoriKey Stop the MaruMori connection and forget the key
	// (DELETE /marumori/key)
	DeleteMaruMoriKey(w http.ResponseWriter, r *http.Request)
	// SetMaruMoriKey Store the Learner's MaruMori API key
	// (PUT /marumori/key)
	SetMaruMoriKey(w http.ResponseWriter, r *http.Request)
	// SyncMaruMori Sync the Learner's knowledge state from MaruMori now
	// (POST /marumori/sync)
	SyncMaruMori(w http.ResponseWriter, r *http.Request)
	// ListMaruMoriSyncs The Learner's recent Sync runs, newest first
	// (GET /marumori/syncs)
	ListMaruMoriSyncs(w http.ResponseWriter, r *http.Request)
	// GetMe The authenticated user
	// (GET /me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// StartPracticeSession Start a Practice Session drawn from the Focus Set
	// (POST /practice/sessions)
	StartPracticeSession(w http.ResponseWriter, r *http.Request)
	// GetPracticeSession A Practice Session in progress, or its results once complete
	// (GET /practice/sessions/{sessionId})
	GetPracticeSession(w http.ResponseWriter, r *http.Request, sessionId SessionId)
	// AnswerPracticeExercise Answer one exercise of a Practice Session
	// (POST /practice/sessions/{sessionId}/answers)
	AnswerPracticeExercise(w http.ResponseWriter, r *http.Request, sessionId SessionId)
	// GetStartingLevel The Learner's declared Starting Level, if they have chosen one
	// (GET /starting-level)
	GetStartingLevel(w http.ResponseWriter, r *http.Request)
	// SetStartingLevel Choose or change the Starting Level
	// (PUT /starting-level)
	SetStartingLevel(w http.ResponseWriter, r *http.Request)
}

